   264			}
   265		}
   266	}
   267	
   268	// recordLongestBacktickRun は s の中で最も長く続くバッククォートの数を返す。
   269	func recordLongestBacktickRun(s string) int {
   270		longest, run := 0, 0
   271		for _, r := range s {
   272			if r == '`' {
   273				run++
   274				if run > longest {
   275					longest = run
   276				}
   277			} else {
   278				run = 0
   279			}
   280		}
   281		return longest
   282	}

