   169						add("chosen_option %q は %s の案 %q のパッチで覆う案なのに、%s の chosen_option が %q です (1 つの修正で覆う問題は、同じ回答で参照先の案も選ぶ)",
   170							c, ref.ProblemID, ref.Option, ref.ProblemID, other.ChosenOption)
   171					}
   172				}
   173			}
   174		} else if (pl.Status == "pending" || pl.Status == "done") && len(pl.OptionPatches) > 0 {
   175			// 案を選んで pending にした問題は、修正フェーズが chosen_option の案のパッチを当てる (SKILL.md の手順 1 の
   176			// 「人間の回答の反映」)。無いと、人間が見たパッチを当てずに approach の文から直すことになる。
   177			add("status %s で option_patches があるのに、chosen_option がありません (人間が選んだ案のラベルを書く。修正フェーズは、その案のパッチを当てる)", pl.Status)
   178		}
   179		// 参照先の問題が、この問題の covered_by が指す案を選んだなら、この問題も同じ回答でその案を選ぶ。
   180		// 選んでいないと、修正フェーズが参照先のパッチを当て、この問題の変更が人間の選ばないままコミットされる。
   181		for _, op := range pl.OptionPatches {
   182			ref := op.CoveredBy
   183			if ref == nil || ref.ProblemID == pl.ProblemID || pl.ChosenOption == op.Option {
   184				continue
   185			}
   186			for _, other := range plans {
   187				if other.ProblemID == ref.ProblemID && other.ChosenOption != "" && other.ChosenOption == ref.Option &&
   188					(other.Status == "pending" || other.Status == "done") {
   189					add("%s が案 %q を選んでおり、そのパッチはこの問題の案 %q も覆うのに、この問題の chosen_option が %q です (1 つの修正で覆う問題は、同じ回答で両方の案を選ぶ)",
   190						ref.ProblemID, ref.Option, op.Option, pl.ChosenOption)
   191				}
   192			}
   193		}
   194		return problems
   195	}
   196	
   197	// recordPatchRefProblems は covered_by の参照を検査する。参照先は、同じ回の、ほかの問題の、パッチを持つ要素。
   198	func recordPatchRefProblems(self string, ref recordPatchRef, plans []recordPlan) []string {
   199		var problems []string
   200		if ref.ProblemID == "" {
   201			problems = append(problems, "covered_by.problem_id がありません")
   202		}
   203		if ref.Option == "" {
   204			problems = append(problems, "covered_by.option がありません")
   205		}
   206		if ref.ProblemID == "" || ref.Option == "" {
   207			return problems
   208		}
   209		if ref.ProblemID == self {
   210			return append(problems, "covered_by が自分の問題を指しています (覆うのはほかの問題の案のパッチ)")
   211		}
   212		for _, other := range plans {
   213			if other.ProblemID != ref.ProblemID {
   214				continue
   215			}
   216			for _, op := range other.OptionPatches {
   217				if op.Option != ref.Option {
   218					continue
   219				}
   220				if op.Patch == "" {
   221					problems = append(problems, fmt.Sprintf("covered_by が指す %s の案 %q は、パッチを持つ要素ではありません", ref.ProblemID, ref.Option))
   222				}
   223				return problems
   224			}
   225			return append(problems, fmt.Sprintf("covered_by の案 %q は、問題 %s の option_patches にありません", ref.Option, ref.ProblemID))
   226		}
   227		return append(problems, fmt.Sprintf("covered_by の問題 %q は同じ回の plans にありません", ref.ProblemID))
   228	}
   229	
   230	// renderOptionPatches は option_patches を持つ問題の小節「#### <問題> の案」を書く。要素ごとに、options の
   231	// 該当の行と、パッチ (diff のコードブロック)・ファイルを変えないこと・覆う参照のどれかを出す。
   232	// option_patches の無い問題には何も書かない。無い記録の出力が変わると、既存のサマリがすべて古いと報告されるため。
   233	func renderOptionPatches(b *strings.Builder, pl recordPlan) {
   234		if len(pl.OptionPatches) == 0 {
   235			return
   236		}
   237		fmt.Fprintf(b, "\n#### %s の案\n", recordCell(pl.ProblemID))
   238		if pl.ChosenOption != "" {
   239			fmt.Fprintf(b, "\n選んだ案: %s\n", recordCell(pl.ChosenOption))
   240		}
   241		lines := recordOptionLines(pl.Options)
   242		for _, op := range pl.OptionPatches {
   243			// 案の行。options に無いラベル (検査が報告する) は、ラベルだけを出す。
   244			text := op.Option
   245			for _, line := range lines {
   246				if line.label != "" && line.label == op.Option {
   247					text = line.text
   248					break
   249				}
   250			}
   251			fmt.Fprintf(b, "\n%s\n", recordCell(text))
   252			switch {
   253			case op.Patch != "":
   254				fence := strings.Repeat("`", max(3, recordLongestBacktickRun(op.Patch)+1))
   255				patch := op.Patch
   256				if !strings.HasSuffix(patch, "\n") {
   257					patch += "\n"
   258				}
   259				fmt.Fprintf(b, "\nパッチ (起点 `%s`):\n\n%sdiff\n%s%s\n", recordCell(op.Base), fence, patch, fence)
   260			case op.NoChange != nil && *op.NoChange:
   261				b.WriteString("\nファイルを変えない。\n")
   262			case op.CoveredBy != nil:
   263				fmt.Fprintf(b, "\n%s の案 %s のパッチで覆う。\n", recordCell(op.CoveredBy.ProblemID), recordCell(op.CoveredBy.Option))
   264			}
   265		}
   266	}
   267	
   268	// recordLongestBacktickRun は s の中で最も長く続くバッククォートの数を返す。
   269	func recordLongestBacktickRun(s string) int {
   270		longest, run := 0, 0
   271		for _, r := range s {
   272			if r == '`' {
   273				run++
   274				if run > longest {
   275					longest = run
   276				}
   277			} else {
   278				run = 0
   279			}
   280		}
   281		return longest
   282	}

